from __future__ import annotations
from pathlib import Path

from lxml import etree

from taf.ul.ue.sim.env_setup.settings import CUSTOM_CONFIG
from taf.ul.ue.sim.env_setup.utils.enums import SimConfigType, DevicesNames
from taf.ul.ue.sim.env_setup.utils.dict_types import RtgCusConfigType


def verify_iphy_airphone_xml_has_any_rmod(xml_path: str) -> None:
    parsed_xml = etree.parse(xml_path)
    assert (
        len(parsed_xml.findall(".//identity")) >= 1
    ), "No RMODs found in IPhy/AirPhone configuration. Fix config file."


def prepare_input_airphone_config(sim_config: str) -> dict[str, str | int]:
    custom_config_path = CUSTOM_CONFIG.joinpath(sim_config)
    if custom_config_path.exists():
        verify_iphy_airphone_xml_has_any_rmod(custom_config_path.as_posix())
        return {"file": custom_config_path.as_posix(), "api": SimConfigType.AIRPHONE_XML}
        # todo check if we can remove .as_posix()
    return prepare_input_iphy_config(sim_config)


def prepare_input_iphy_config(sim_config: str) -> dict[str, str | int]:
    if Path(sim_config).exists():
        verify_iphy_airphone_xml_has_any_rmod(sim_config)
        return {"file": sim_config, "api": SimConfigType.IPHY_XML}
        # todo check if we can remove .as_posix()
    raise FileNotFoundError(f"Path {sim_config} doesn't exists as absolute path")


def __prepare_input_rtg_cus_single_file(sim_config: str) -> RtgCusConfigType:
    config_path = Path(sim_config)
    if not config_path.exists():
        raise FileNotFoundError(f"Path {sim_config} doesn't exists as absolute path")
    if config_path.suffix in (".yml", ".yaml"):
        return {"file": sim_config, "api": SimConfigType.CUS_YAML, "db": ""}
    elif config_path.suffix == ".ini":
        return {"file": sim_config, "api": SimConfigType.CUS_INI, "db": ""}
    else:
        raise TypeError(f"Wrong format of file: {config_path.suffix}. Possible formats are [.ini, .yml, .yaml]")


def __prepare_input_rtg_cus_two_files(parsed_configs: list) -> RtgCusConfigType:
    for config_fp in parsed_configs:
        config = Path(config_fp)
        if not config.exists():
            raise FileNotFoundError(f"Path {config} doesn't exists as absolute path")
        # todo check if can provide Path object, not strings
        if config.suffix.lower() == ".db":
            db_file = config.as_posix()
        elif config.suffix.lower() == ".ini":
            conf_file = config.as_posix()
        else:
            TypeError(f"Wrong type of file {config.suffix}. Allowed types: [.yml, .yaml, .ini, .db]")
    return RtgCusConfigType(api=SimConfigType.CUS_INI, db=db_file, file=conf_file)


def prepare_input_rtg_cus_config(sim_config: str) -> RtgCusConfigType:
    parsed_configs = parse_conf_data_to_list(sim_config)
    if len(parsed_configs) == 1:
        return __prepare_input_rtg_cus_single_file(parsed_configs[0])
    elif len(parsed_configs) == 2:
        return __prepare_input_rtg_cus_two_files(parsed_configs)
    raise AttributeError(f"More than 2 files provided. Not known action. [{parsed_configs}]")


def parse_conf_data_to_list(config_data: str | list[str] | None) -> list[str]:
    if config_data is None or config_data == "":
        return []
    elif isinstance(config_data, str):
        return [str(conf).strip() for conf in config_data.split(",")]
    elif isinstance(config_data, (tuple, list)):
        return [str(conf).strip() for conf in config_data]
    else:
        raise AttributeError(
            "Simulator configuration unparsable. Please provide path as single string, "
            "comma-separated string or list of string"
        )


def convert_sim_type_to_enum(sim_type):
    if (name := sim_type.lower()) == DevicesNames.AIRPHONE.lower():
        sim_type = DevicesNames.AIRPHONE
    elif name == DevicesNames.CUS.lower():
        sim_type = DevicesNames.CUS
    elif name == DevicesNames.IPHY.lower():
        sim_type = DevicesNames.IPHY
    elif name == DevicesNames.RTG.lower():
        sim_type = DevicesNames.RTG
    else:
        raise ValueError("Unsupported simulator type. ")
    return sim_type
